  width: stretch; /* Safari 27+ */
  width: -webkit-fill-available; /* fallback régebbi iOS-re */
}




 2. Face ID / Touch ID – WebAuthn API

Face ID PWAból teljes mértékben elérhető. A WebAuthn API Safari 14 (iOS 14) óta működik, tehát minden iOS 27es eszközön stabil. Ez valódi biometrikus hitelesítés – nem fake:[6][7]

javascript
// REGISZTRÁCIÓ (első bejelentkezés - Face ID párosítás)
async function registerFaceID(username) {
  // A challenget a SZERVERRŐL kell lekérni (FONTOS!)
  const challengeResponse = await fetch('/api/auth/challenge', {
    method: 'POST',
    body: JSON.stringify({ username }),
    headers: { 'Content-Type': 'application/json' }
  });
  const { challenge, userId } = await challengeResponse.json();

  const credential = await navigator.credentials.create({
    publicKey: {
      challenge: base64ToBuffer(challenge),
      rp: {
        name: "Az Appom",
        id: "appdomain.com"  // ← a te domainedet írd ide
      },
      user: {
        id: base64ToBuffer(userId),
        name: username,
        displayName: username
      },
      pubKeyCredParams: [
        { type: "public-key", alg: -7 },   // ES256 – Face ID preferált
        { type: "public-key", alg: -257 }  // RS256 – fallback
      ],
      authenticatorSelection: {
        authenticatorAttachment: "platform",  // ← CSAK eszközbeépített (Face ID/Touch ID)
        userVerification: "required",         // ← Face ID kötelező
        residentKey: "preferred"              // Passkey tárolás
      },
      timeout: 60000,
      attestation: "none"
    }
  });

  // Küld el a szervernek tárolásra
  await fetch('/api/auth/register', {
    method: 'POST',
    body: JSON.stringify({
      credentialId: bufferToBase64(credential.rawId),
      publicKey: bufferToBase64(credential.response.getPublicKey()),
      username
    }),
    headers: { 'Content-Type': 'application/json' }
  });
}

// BEJELENTKEZÉS (Face ID scan)
async function loginWithFaceID() {
  const { challenge } = await fetch('/api/auth/login-challenge').then(r => r.json());

  const assertion = await navigator.credentials.get({
    publicKey: {
      challenge: base64ToBuffer(challenge),
      rpId: "appdomain.com",
      userVerification: "required",  // Face ID scan aktiválása
      timeout: 60000
    }
  });

  const result = await fetch('/api/auth/verify', {
    method: 'POST',
    body: JSON.stringify({
      credentialId: bufferToBase64(assertion.rawId),
      signature: bufferToBase64(assertion.response.signature),
      authenticatorData: bufferToBase64(assertion.response.authenticatorData),
      clientDataJSON: bufferToBase64(assertion.response.clientDataJSON)
    }),
    headers: { 'Content-Type': 'application/json' }
  });

  return result.ok;
}

// Feature detection + iOS ellenőrzés
async function checkBiometricSupport() {
  if (!window.PublicKeyCredential) return false;

  // Platform authenticator (Face ID / Touch ID) ellenőrzése
  const available = await PublicKeyCredential
    .isUserVerifyingPlatformAuthenticatorAvailable();

  return available;
}

// Helper függvények
function base64ToBuffer(base64) {
  return Uint8Array.from(atob(base64.replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0));
}
function bufferToBase64(buffer) {
  return btoa(String.fromCharCode(...new Uint8Array(buffer)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
}


