 3. Natív Push Értesítések (iOS 16.4+, minden iOS 27 eszközön)

Push csak Home Screenről telepített PWAból működik iOSen. Safari 18.4 bevezette a Declarative Web Pusht is, ami szerveren jóval egyszerűbb:[9][10]

javascript
// TELJES PUSH SETUP (iOS 27 kompatibilis)

const VAPID_PUBLIC_KEY = 'HELYETTESÍTSD_A_SAJÁT_KULCSODDAL';

async function setupPushNotifications() {
  // 1. Ellenőrzés
  if (!('PushManager' in window)) {
    console.warn('Push API nem elérhető (talán nem Home Screen app?)');
    return;
  }

  // iOS-en push CSAK standalone módban működik
  const isStandalone = window.navigator.standalone === true;
  if (!isStandalone && /iPhone|iPad|iPod/.test(navigator.userAgent)) {
    showInstallPrompt(); // Mutasd az Add to Home Screen instrukciót
    return;
  }

  // 2. Engedély kérés (USER GESTURE szükséges - gombon belül hívd!)
  const permission = await Notification.requestPermission();
  if (permission !== 'granted') return;

  // 3. Service Worker kész megvárása
  const registration = await navigator.serviceWorker.ready;

  // 4. Feliratkozás
  const subscription = await registration.pushManager.subscribe({
    userVisibleOnly: true,  // iOS-en KÖTELEZŐ true
    applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
  });

  // 5. Mentés szerverre
  await fetch('/api/push/subscribe', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      endpoint: subscription.endpoint,
      keys: {
        p256dh: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey('p256dh')))),
        auth: btoa(String.fromCharCode(...new Uint8Array(subscription.getKey('auth'))))
      }
    })
  });

  console.log('Push értesítések beállítva!');
}

function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = atob(base64);
  return new Uint8Array([...rawData].map(c => c.charCodeAt(0)));
}


