 4. Az Install Prompt iOSen (iOS 26 változással)

iOS 26tól az "Add to Home Screen" dialog automatikusan felajánlja a web app módot. De saját, elegáns install bannert is csinálhatsz:[3]

javascript
class IOSInstallManager {
  constructor() {
    this.isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
    this.iOSVersion = this.getIOSVersion();
    this.isInstalled = window.navigator.standalone === true ||
                       window.matchMedia('(display-mode: standalone)').matches;
  }

  getIOSVersion() {
    const match = navigator.userAgent.match(/OS (\d+)_(\d+)/);
    return match ? parseFloat(`${match[1]}.${match[2]}`) : 0;
  }

  shouldShowPrompt() {
    if (!this.isIOS || this.isInstalled) return false;
    const dismissed = sessionStorage.getItem('installDismissed');
    return !dismissed;
  }

  showInstallBanner() {
    if (!this.shouldShowPrompt()) return;

    const banner = document.createElement('div');
    banner.className = 'ios-install-banner';
    banner.innerHTML = `
      <div class="install-content">
        <img src="/icons/icon-64.png" alt="App ikon" width="48" height="48">
        <div class="install-text">
          <strong>Telepítsd az appot!</strong>
          <span>Koppints a <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8M16 6l-4-4-4 4M12 2v13"/></svg> gombra, majd "Add to Home Screen"</span>
        </div>
        <button class="install-dismiss" aria-label="Bezárás">✕</button>
      </div>
      <div class="install-arrow">▼</div>
    `;

    banner.querySelector('.install-dismiss').addEventListener('click', () => {
      banner.remove();
      sessionStorage.setItem('installDismissed', '1');
    });

    document.body.appendChild(banner);
  }
}

